def pair_counts(ids):
    counts = {}
    for a, b in zip(ids, ids[1:]):
        counts[(a, b)] = counts.get((a, b), 0) + 1
    return counts

def most_common_pair(ids):
    counts = {}
    for a, b in zip(ids, ids[1:]):
        counts[(a, b)] = counts.get((a, b), 0) + 1
    if not counts:
        return None
    return max(counts, key=lambda p: (counts[p], -p[0], -p[1]))

def merge_pair(ids, pair, new_id):
    out, i = [], 0
    while i < len(ids):
        if i + 1 < len(ids) and (ids[i], ids[i + 1]) == tuple(pair):
            out.append(new_id)
            i += 2
        else:
            out.append(ids[i])
            i += 1
    return out

import math

def cross_entropy(logits, target):
    z = [float(x) for x in logits]
    m = max(z)
    lse = m + math.log(sum(math.exp(x - m) for x in z))
    return float(lse - z[target])

import math

def causal_mask(scores):
    out = []
    for i, row in enumerate(scores):
        new = [float(x) for x in row]
        for j in range(len(new)):
            if j > i:
                new[j] = -math.inf
        out.append(new)
    return out

import math

def layer_norm(x, eps=1e-5):
    out = []
    for row in x:
        row = [float(v) for v in row]
        mean = sum(row) / len(row)
        var = sum((v - mean) ** 2 for v in row) / len(row)
        out.append([(v - mean) / math.sqrt(var + eps) for v in row])
    return out

import math

def gelu(x):
    c = math.sqrt(2.0 / math.pi)
    def one(v):
        v = float(v)
        return 0.5 * v * (1.0 + math.tanh(c * (v + 0.044715 * v ** 3)))
    if isinstance(x, (list, tuple)):
        return [one(v) for v in x]
    return one(x)

import math

def top_k(logits, k):
    z = [float(v) for v in logits]
    if k < len(z):
        order = sorted(range(len(z)), key=lambda i: z[i])
        for i in order[:-k]:
            z[i] = -math.inf
    return z

